define("POST /api/company/imports/expenses/preview", "expense-imports.ts", "Prepare and persist a paid-expense CSV review", "JSON body limit532480 bytes; csv is nonempty UTF8 up to256KiB and500 data rows. Required headers: sourceId,propertyId,occurredOn,amount,category; optional memo. Namespace is1–100 lowercase letters/digits/dot/underscore/hyphen; exact source IDs must be unique within the file and not previously imported under that namespace, even after void. Every row issue is returned; totalsComplete=false denotes only the valid-row subtotal. Creates a review batch/audit, never cash. Durable key is company-scoped across import actions.", importDetail, { body: obj({ sourceNamespace: { type: "string", pattern: "^[a-z0-9][a-z0-9._-]{0,99}$" }, fileName: text(200), csv: { type: "string", description: "RFC4180 UTF8 CSV, maximum256KiB and500 data rows; no rows are silently omitted." }, submissionKey: uuid }) });
